    lemon: () => { face('sour', 2.5); line(L('好…好酸！', 'S-so sour!')); aura(2.5, { draw(g, b, k) { const h = b.p[0]; g.strokeStyle = '#e8d020'; g.lineWidth = 3; g.globalAlpha = Math.min(1, k * 3); for (let j = 0; j < 6; j++) { const a = j / 6 * TAU + performance.now() / 400; g.beginPath(); g.moveTo(h.x + Math.cos(a) * 38, h.y + Math.sin(a) * 38); g.lineTo(h.x + Math.cos(a) * 50, h.y + Math.sin(a) * 50); g.stroke(); } } }); },
