    burger: (x, y) => { const layers = [['#e8a040', 14], ['#6ac04a', 6], ['#ffd23a', 5], ['#6a3a1a', 10], ['#e8a040', 10]]; layers.forEach(([c, h], j) => after(j * 0.1, () => onPart(4, 0, (g, k) => { g.fillStyle = c; const yy = -36 - layers.slice(0, j).reduce((s, l) => s + l[1], 0); g.beginPath(); g.roundRect(-26, yy - h, 52, h, j === layers.length - 1 ? [16, 16, 4, 4] : 4); g.fill(); }))); },
