    bday: () => { C.sfx('chime'); onPart(4, 0, (g) => { for (let j = -1; j <= 1; j++) { g.fillStyle = ['#ff6aa8', '#7ad0ff', '#ffe14a'][j + 1]; g.fillRect(j * 12 - 2, -50, 5, 18); g.fillStyle = '#ffb02e'; g.beginPath(); g.ellipse(j * 12 + 0.5, -55 + Math.sin(performance.now() / 60 + j) * 1, 3, 6, 0, 0, TAU); g.fill(); } }); word(pt(0).x, pt(0).y - 110, L('生日快樂！', 'HAPPY BIRTHDAY!'), '#ff8ad8'); },
