    paint: (x, y) => { const c = pick(RAINBOW); for (let j = 0; j < 6; j++) { const px = x + rnd(-200, 200), py = y + rnd(-200, 60), r = rnd(14, 34), cc = pick(RAINBOW), blob = Array.from({ length: 10 }, () => rnd(0.6, 1.3)); mark(12, (g, k) => { g.globalAlpha = Math.min(1, k * 3) * 0.8; g.fillStyle = cc; g.beginPath(); blob.forEach((q, n) => { const a = n / blob.length * TAU; g.lineTo(px + Math.cos(a) * r * q, py + Math.sin(a) * r * q); }); g.fill(); }); } },
