    squid: () => { const blots = Array.from({ length: 6 }, () => [rnd(0.1, 0.9), rnd(0.1, 0.8), rnd(40, 110)]); screen(2.6, (g, k, W, H) => { g.globalAlpha = Math.min(1, k * 2) * 0.9; g.fillStyle = '#16161e'; for (const [u, v, r] of blots) { g.beginPath(); g.arc(u * W, v * H + (1 - k) * 80, r, 0, TAU); g.fill(); g.beginPath(); g.ellipse(u * W, v * H + r + (1 - k) * 160, r * 0.25, r * 0.7, 0, 0, TAU); g.fill(); } }); },
    snail: () => { aura(5, { draw(g, b, k) { const path = [12, 10, 8, 2, 1, 0], u = (1 - k) * (path.length - 1), j = Math.floor(u), f = u - j, a = b.p[path[j]], c = b.p[path[Math.min(path.length - 1, j + 1)]]; g.globalAlpha = Math.min(1, k * 5); g.strokeStyle = '#c8e8a088'; g.lineWidth = 5; g.beginPath(); g.moveTo(b.p[path[0]].x, b.p[path[0]].y); for (let q = 1; q <= j; q++) g.lineTo(b.p[path[q]].x, b.p[path[q]].y); g.lineTo(a.x + (c.x - a.x) * f, a.y + (c.y - a.y) * f); g.stroke(); C.emoji('🐌', a.x + (c.x - a.x) * f + 10, a.y + (c.y - a.y) * f, 26); } }); },
    basket: (x, y) => { const { W } = D(), hx = x < W / 2 ? W - 120 : 120, hy = 230; fxd(hx, hy, 2.4, (g, k, f) => { g.globalAlpha = Math.min(1, k * 4, (1 - k) * 10); g.fillStyle = '#ffffff'; g.strokeStyle = '#c8c8c8'; g.lineWidth = 3; g.fillRect(f.x - 40, f.y - 60, 80, 54); g.strokeRect(f.x - 40, f.y - 60, 80, 54); g.strokeStyle = '#e0482a'; g.lineWidth = 5; g.beginPath(); g.ellipse(f.x, f.y, 26, 6, 0, 0, TAU); g.stroke(); g.strokeStyle = '#ffffffcc'; g.lineWidth = 1.5; for (let q = -2; q <= 2; q++) { g.beginPath(); g.moveTo(f.x + q * 10, f.y); g.lineTo(f.x + q * 6, f.y + 30); g.stroke(); } }); fxd(x, y, 0.9, (g, k, f) => { const u = 1 - k; C.emoji('🏀', x + (hx - x) * u, y + (hy - 10 - y) * u - Math.sin(u * Math.PI) * 180, 34, u * 10); }); after(0.9, () => { C.sfx('swish'); C.sfx('cheer'); word(hx, hy - 80, 'SWISH! +2', '#ff8a2a'); }); },
