    yarn: () => { C.sfx('meow'); aura(3, { draw(g, b, k) { const c = chest(); g.strokeStyle = '#ff6a8a'; g.lineWidth = 2.5; g.globalAlpha = Math.min(1, k * 3); g.beginPath(); for (let q = 0; q < 60 * (1 - k * 0.5); q++) { const a = q * 0.7; g.lineTo(c.x + Math.cos(a) * 34, c.y - 50 + q * 2.2); } g.stroke(); } }); const { FLOOR } = D(); fxd(feet().x + 60, FLOOR - 20, 3, (g, k, f) => { g.globalAlpha = Math.min(1, k * 4); C.emoji('🐱', f.x, f.y - Math.abs(Math.sin(f.life * 8)) * 10, 40); }); },
